using System;
using System.Text.Json.Serialization;
using AmazonSwf.Core.Enum;

namespace AmazonSwf.Models.Enums;

/// <summary>
/// The cause of the failure. This information is generated by the system and can be useful for diagnostic purposes. If cause is set to OPERATION_NOT_PERMITTED, the decision failed because it lacked sufficient permissions. For details and example IAM policies, see Using IAM to Manage Access to Amazon SWF Workflows in the Amazon SWF Developer Guide.
/// </summary>
[JsonConverter(typeof(StringEnumConverter<Cause3>))]
public sealed record Cause3 : OpenStringEnum<Cause3>
{
    private Cause3(string value) : base(value)
    {
    }

    public static readonly Cause3 UnhandledDecision = new("UNHANDLED_DECISION");

    public static readonly Cause3 WorkflowTypeDeprecated = new("WORKFLOW_TYPE_DEPRECATED");

    public static readonly Cause3 WorkflowTypeDoesNotExist = new("WORKFLOW_TYPE_DOES_NOT_EXIST");

    public static readonly Cause3 DefaultExecutionStartToCloseTimeoutUndefined = new(
        "DEFAULT_EXECUTION_START_TO_CLOSE_TIMEOUT_UNDEFINED");

    public static readonly Cause3 DefaultTaskStartToCloseTimeoutUndefined = new(
        "DEFAULT_TASK_START_TO_CLOSE_TIMEOUT_UNDEFINED");

    public static readonly Cause3 DefaultTaskListUndefined = new("DEFAULT_TASK_LIST_UNDEFINED");

    public static readonly Cause3 DefaultChildPolicyUndefined = new("DEFAULT_CHILD_POLICY_UNDEFINED");

    public static readonly Cause3 ContinueAsNewWorkflowExecutionRateExceeded = new(
        "CONTINUE_AS_NEW_WORKFLOW_EXECUTION_RATE_EXCEEDED");

    public static readonly Cause3 OperationNotPermitted = new("OPERATION_NOT_PERMITTED");

    public TResult Match<TResult>(Func<TResult> onUnhandledDecision,
        Func<TResult> onWorkflowTypeDeprecated,
        Func<TResult> onWorkflowTypeDoesNotExist,
        Func<TResult> onDefaultExecutionStartToCloseTimeoutUndefined,
        Func<TResult> onDefaultTaskStartToCloseTimeoutUndefined,
        Func<TResult> onDefaultTaskListUndefined,
        Func<TResult> onDefaultChildPolicyUndefined,
        Func<TResult> onContinueAsNewWorkflowExecutionRateExceeded,
        Func<TResult> onOperationNotPermitted,
        Func<string, TResult> otherwise) =>
        this switch
        {
            _ when this == UnhandledDecision => onUnhandledDecision(),
            _ when this == WorkflowTypeDeprecated => onWorkflowTypeDeprecated(),
            _ when this == WorkflowTypeDoesNotExist => onWorkflowTypeDoesNotExist(),
            _ when this ==
                DefaultExecutionStartToCloseTimeoutUndefined => onDefaultExecutionStartToCloseTimeoutUndefined(),
            _ when this == DefaultTaskStartToCloseTimeoutUndefined => onDefaultTaskStartToCloseTimeoutUndefined(),
            _ when this == DefaultTaskListUndefined => onDefaultTaskListUndefined(),
            _ when this == DefaultChildPolicyUndefined => onDefaultChildPolicyUndefined(),
            _ when this == ContinueAsNewWorkflowExecutionRateExceeded => onContinueAsNewWorkflowExecutionRateExceeded(),
            _ when this == OperationNotPermitted => onOperationNotPermitted(),
            _ => otherwise(Value)
        };

    public void Match(Action onUnhandledDecision,
        Action onWorkflowTypeDeprecated,
        Action onWorkflowTypeDoesNotExist,
        Action onDefaultExecutionStartToCloseTimeoutUndefined,
        Action onDefaultTaskStartToCloseTimeoutUndefined,
        Action onDefaultTaskListUndefined,
        Action onDefaultChildPolicyUndefined,
        Action onContinueAsNewWorkflowExecutionRateExceeded,
        Action onOperationNotPermitted,
        Action<string> otherwise)
    {
        if (this == UnhandledDecision) onUnhandledDecision();
        else if (this == WorkflowTypeDeprecated) onWorkflowTypeDeprecated();
        else if (this == WorkflowTypeDoesNotExist) onWorkflowTypeDoesNotExist();
        else if (this == DefaultExecutionStartToCloseTimeoutUndefined) onDefaultExecutionStartToCloseTimeoutUndefined();
        else if (this == DefaultTaskStartToCloseTimeoutUndefined) onDefaultTaskStartToCloseTimeoutUndefined();
        else if (this == DefaultTaskListUndefined) onDefaultTaskListUndefined();
        else if (this == DefaultChildPolicyUndefined) onDefaultChildPolicyUndefined();
        else if (this == ContinueAsNewWorkflowExecutionRateExceeded) onContinueAsNewWorkflowExecutionRateExceeded();
        else if (this == OperationNotPermitted) onOperationNotPermitted();
        else otherwise(Value);
    }
}
